<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();$pdo=db();
if(is_post()){try{verify_csrf();$action=scalar_string($_POST['action']??'save');$id=max(0,scalar_int($_POST['id']??0));if($action==='toggle'){$pdo->prepare('UPDATE coupons SET is_active=1-is_active WHERE id=?')->execute([$id]);flash('success','وضعیت کد تغییر کرد.');redirect(app_url('admin/coupons.php'));}
    $code=normalize_coupon_code(scalar_string($_POST['code']??''));$title=trim(scalar_string($_POST['title']??''));$type=scalar_string($_POST['discount_type']??'percent');$valueOk=false;$value=bounded_uint($_POST['discount_value']??'',MAX_MONEY_AMOUNT,$valueOk);$minimumOk=false;$minimum=bounded_uint($_POST['minimum_order']??'0',MAX_MONEY_AMOUNT,$minimumOk);$maximumRaw=trim(scalar_string($_POST['maximum_discount']??''));$maximumOk=true;$maximum=$maximumRaw===''?null:bounded_uint($maximumRaw,MAX_MONEY_AMOUNT,$maximumOk);$usageRaw=trim(scalar_string($_POST['usage_limit']??''));$usage=$usageRaw===''?null:max(1,min(1000000000,scalar_int($usageRaw)));$per=max(1,min(1000,scalar_int($_POST['per_customer_limit']??1,1)));$starts=trim(scalar_string($_POST['starts_at']??''))?:null;$ends=trim(scalar_string($_POST['ends_at']??''))?:null;
    if(!preg_match('/^[A-Z0-9_-]{2,60}$/',$code)||text_length($title)<2||text_length($title)>160||!in_array($type,['percent','fixed'],true)||!$valueOk||!$minimumOk||!$maximumOk||$value<1||($type==='percent'&&$value>100))throw new RuntimeException('اطلاعات کد تخفیف معتبر نیست.');if(($starts&&strtotime($starts)===false)||($ends&&strtotime($ends)===false))throw new RuntimeException('تاریخ معتبر نیست.');if($starts&&$ends&&strtotime($ends)<=strtotime($starts))throw new RuntimeException('تاریخ پایان باید بعد از شروع باشد.');$starts=$starts?str_replace('T',' ',$starts).':00':null;$ends=$ends?str_replace('T',' ',$ends).':00':null;
    if($id)$pdo->prepare('UPDATE coupons SET code=?,title=?,discount_type=?,discount_value=?,minimum_order=?,maximum_discount=?,usage_limit=?,per_customer_limit=?,starts_at=?,ends_at=?,is_active=? WHERE id=?')->execute([$code,$title,$type,$value,$minimum,$maximum,$usage,$per,$starts,$ends,isset($_POST['is_active'])?1:0,$id]);
    else{$pdo->prepare('INSERT INTO coupons(code,title,discount_type,discount_value,minimum_order,maximum_discount,usage_limit,per_customer_limit,starts_at,ends_at,is_active,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$code,$title,$type,$value,$minimum,$maximum,$usage,$per,$starts,$ends,isset($_POST['is_active'])?1:0,(int)admin_user()['id']]);$id=(int)$pdo->lastInsertId();}
    flash('success','کد تخفیف ذخیره شد.');redirect(app_url('admin/coupons.php?edit='.$id));
}catch(Throwable $e){flash('error',$e instanceof PDOException?'کد تکراری است یا اطلاعات معتبر نیست.':$e->getMessage());redirect(app_url('admin/coupons.php'));}}
$editId=max(0,scalar_int($_GET['edit']??0));$edit=null;if($editId){$s=$pdo->prepare('SELECT * FROM coupons WHERE id=?');$s->execute([$editId]);$edit=$s->fetch()?:null;}$rows=$pdo->query('SELECT c.*,(SELECT COUNT(*) FROM coupon_usages u WHERE u.coupon_id=c.id) used_count,COALESCE((SELECT SUM(discount_amount) FROM coupon_usages u WHERE u.coupon_id=c.id),0) discount_total FROM coupons c ORDER BY id DESC')->fetchAll();
$adminPage='coupons';$adminTitle='کدهای تخفیف';require __DIR__.'/partials/header.php';?>
<div class="admin-title"><h1>کدهای تخفیف</h1></div><form method="post" class="card"><?=csrf_field()?><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="form-grid"><div class="field"><label>کد انگلیسی</label><input name="code" dir="ltr" maxlength="60" value="<?=e($edit['code']??'')?>" required></div><div class="field"><label>عنوان</label><input name="title" maxlength="160" value="<?=e($edit['title']??'')?>" required></div><div class="field"><label>نوع</label><select name="discount_type"><option value="percent" <?=($edit['discount_type']??'percent')==='percent'?'selected':''?>>درصدی</option><option value="fixed" <?=($edit['discount_type']??'')==='fixed'?'selected':''?>>مبلغ ثابت</option></select></div><div class="field"><label>مقدار</label><input type="number" name="discount_value" min="1" value="<?=e($edit['discount_value']??'')?>" required></div><div class="field"><label>حداقل سفارش (تومان)</label><input type="number" name="minimum_order" min="0" value="<?=e($edit['minimum_order']??0)?>"></div><div class="field"><label>سقف تخفیف (اختیاری)</label><input type="number" name="maximum_discount" min="0" value="<?=e($edit['maximum_discount']??'')?>"></div><div class="field"><label>سقف مصرف کل (اختیاری)</label><input type="number" name="usage_limit" min="1" value="<?=e($edit['usage_limit']??'')?>"></div><div class="field"><label>سقف هر مشتری</label><input type="number" name="per_customer_limit" min="1" max="1000" value="<?=e($edit['per_customer_limit']??1)?>"></div><div class="field"><label>شروع</label><input type="datetime-local" name="starts_at" value="<?=e(isset($edit['starts_at'])?str_replace(' ','T',substr((string)$edit['starts_at'],0,16)):'')?>"></div><div class="field"><label>پایان</label><input type="datetime-local" name="ends_at" value="<?=e(isset($edit['ends_at'])?str_replace(' ','T',substr((string)$edit['ends_at'],0,16)):'')?>"></div><div class="field full checkboxes"><label><input type="checkbox" name="is_active" <?=!isset($edit['is_active'])||$edit['is_active']?'checked':''?>> فعال</label></div></div><button class="btn btn-primary">ذخیره</button></form>
<div class="card table-wrap"><table><thead><tr><th>کد</th><th>تخفیف</th><th>مصرف</th><th>جمع تخفیف</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong dir="ltr"><?=e($row['code'])?></strong><br><?=e($row['title'])?></td><td><?=$row['discount_type']==='percent'?fa_number($row['discount_value']).'٪':fa_number(format_price($row['discount_value'])).' تومان'?></td><td><?=fa_number($row['used_count'])?><?=isset($row['usage_limit'])?' / '.fa_number($row['usage_limit']):''?></td><td><?=fa_number(format_price($row['discount_total']))?> تومان</td><td><?=$row['is_active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-secondary" href="?edit=<?=$row['id']?>">ویرایش</a></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="6">کدی ساخته نشده است.</td></tr><?php endif?></tbody></table></div>
<?php require __DIR__.'/partials/footer.php';
